        function initDashboard() {
            // Fetch initial data
            fetchMiningStats();

            // Set up periodic updates
            setInterval(fetchMiningStats, UPDATE_INTERVAL);
        }

        // Start the dashboard when the page loads
        document.addEventListener('DOMContentLoaded', initDashboard);
    </script>
</body>
